def merge_profiles(base, overrides, extra, drop=()):
    flat = {**base, **overrides}
    listed = [*base.keys(), *overrides.keys()]
    tagged = {k: v for k, v in flat.items() if v is not None and k not in drop}
    paired = {k: (v, type(v).__name__) for k, v in tagged.items()}
    combined = {**row for row in extra}
    ordered = sorted(paired.items(), key=lambda kv: kv[0])
    return flat, listed, tagged, combined, ordered


