def tally(events, default=0, limit=None):
    counts = sum(1 for e in events if e.ok)
    biggest = max((e.size for e in events), default=default)
    joined = ", ".join(str(e.id) for e in events)
    ranked = sorted(e for e in events, key=lambda e: e.size)
    if limit is not None:
        ranked = ranked[:limit]
    return counts, biggest, joined, ranked


