class Cache:
    hits: int = 0
    misses: int = 0
    last_key: Optional[str] = None

    def record(self, key, found):
        if found:
            self.hits += 1
        else:
            self.misses += 1
        self.last_key = key

    def ratio(self):
        total: int = self.hits + self.misses
        hit, miss: float = 0.0, 0.0
        if total:
            hit = self.hits / total
            miss = self.misses / total
        return hit, miss

