def dispatch(command, match, case):
    type = command.get("type")
    match command:
        case {"type": "move", "x": int() | float() as x, "y": int() | float() as y}:
            return ("move", x, y)
        case {"type": "tag", "names": [*names]} if names:
            return ("tag", names)
        case [("set", key, value), *_] | [("put", key, value)]:
            return ("set", key, value)
        case _ if match == case:
            return ("noop", type)
        case _:
            return ("skip", type)

